10 | $gridClass = match($layout) {
11 |     'hero_split' => 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3',
12 |     'quadrant' => 'grid-cols-1 md:grid-cols-2 lg:grid-cols-2',
