14 |     default => 'grid-cols-1 md:grid-cols-3 lg:grid-cols-4'
15 | };
16 | 
17 | // Map themes to Tailwind classes
18 | $themeContainerClass = match($theme) {
19 |     'oceanic' => 'bg-oceanic-dark dark text-white',
20 |     'accent' => 'bg-oceanic-accent dark text-white',
21 |     'dark' => 'bg-ink dark text-white',
22 |     'slate' => 'bg-slate-teal dark text-white',
23 |     'liberty' => 'bg-liberty-blue dark text-white',
24 |     'heritage' => 'bg-heritage-red dark text-white',
25 |     'gold' => 'bg-warm-gold text-ink',
26 |     'frost' => 'bg-frost-mint text-ink',
27 |     default => 'bg-canvas text-ink'
28 | };
29 | 
30 | $themeCellClass = match($theme) {
31 |     'oceanic', 'accent', 'dark', 'slate', 'liberty', 'heritage' => 'bg-white/5 shadow-xl',
32 |     'gold', 'frost', 'light', '' => 'bg-white shadow-sm',
33 |     default => 'bg-white shadow-sm'
34 | };
35 | 
36 | // Fixed gap strategy per FLUID-GLASS-BENTO-SCHEMA.md
37 | // Instead of margins or variable gaps, we enforce a strict --grid-gap.
38 | ?>
39 | <style>
40 | .bento-container[data-bento-grid] {
41 |     --grid-gap: 2rem;
42 |     --bento-radius: 1.5rem;
43 |     display: grid;
44 |     gap: var(--grid-gap);
45 |     padding: var(--grid-gap);
46 |     grid-auto-rows: minmax(180px, auto);
47 | }
48 | .bento-item {
49 |     border-radius: var(--bento-radius);
50 |     overflow: hidden;
51 |     /* Aspect ratio can be managed by content or utility classes if needed */
52 | }
53 | </style>
54 | 
55 | <section class="bento-container w-full transition-colors duration-500 <?= $themeContainerClass ?> <?= $gridClass ?> grid-flow-dense" data-bento-grid>
56 |     <?php foreach ($block->items()->toBlocks() as $index => $item): ?>
57 |         <?php 
58 |             $colSpanClass = 'col-span-1';
59 |             $rowSpanClass = 'row-span-1';
60 | 
61 |             if ($layout === 'hero_split') {
62 |                 if ($index === 0) {
63 |                     $colSpanClass = 'md:col-span-2 lg:col-span-2';
64 |                     $rowSpanClass = 'md:row-span-2';
65 |                 } elseif ($index === 1) {
66 |                     $rowSpanClass = 'md:row-span-2';
67 |                 }
68 |             } elseif ($layout === 'feature_showcase') {
69 |                 $pattern = $index % 5;
70 |                 if ($pattern === 0) {
71 |                     $colSpanClass = 'md:col-span-2 lg:col-span-2';
72 |                     $rowSpanClass = 'md:row-span-2';
73 |                 } elseif ($pattern === 2) {
74 |                     $colSpanClass = 'md:col-span-2 lg:col-span-2';
75 |                 } elseif ($pattern === 3) {
76 |                     $rowSpanClass = 'md:row-span-2';
77 |                 }
78 |             } elseif ($layout === 'quadrant') {
79 |                 if ($index === 0 || $index === 3) {
80 |                     $rowSpanClass = 'md:row-span-2';
81 |                 }
82 |             }
83 |         ?>
84 |         <article class="bento-item bento-cell transition-all hover:scale-[1.01] <?= $themeCellClass ?> <?= $colSpanClass ?> <?= $rowSpanClass ?>">
85 |             <div class="bento-content-wrapper h-full w-full">
86 |                 <?= snippet('blocks/bento-items/' . $item->type(), ['block' => $item, 'theme' => $theme]) ?>
87 |             </div>
88 |         </article>
89 |     <?php endforeach ?>
90 | </section>
91 |

